import { test, expect } from '@playwright/test';

test('Katy can sign in', async ({ page }) => {
  await page.goto('https://test-automation-banking.vercel.app/');
  await page.getByPlaceholder('Enter Email').fill('katy@gmail.com');
  await page.getByPlaceholder('Enter Password').fill('Katy@12354');
